    () => {
      const pts: Array<[number, number, number]> = [];
      for (let i = 0; i < 9999; i++) {
        if (i % 5 === 0) {
          pts.push([NaN, 0, Infinity]);
        } else if (i % 7 === 0 && pts.length > 0) {
          pts.push([...pts[pts.length - 1]] as [number, number, number]);
        } else {
          const t = i * 0.17;
