      }),
  ],
  [
    'StreamlineGeometry zero/NaN field & 999 seeds',
    () => {
      const seeds: Array<[number, number, number]> = [];
      for (let i = 0; i < 200; i++) {
        seeds.push([i % 2 === 0 ? NaN : 0.2, 0, 0.2]);
      }
      return new Sci.StreamlineGeometry({
        field: () => [0, NaN, Infinity] as const,
        seeds,
        steps: 99999,
        arrowsPerLine: 99,
